package com.earthtrip.planning.adapter.in.web.api.v1.trips.by_trip_id.route_previews;import com.earthtrip.planning.application.port.in.ExecutionPlanningUseCase;import com.earthtrip.sharedkernel.security.CurrentActor;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/trips/{tripId}/route-previews") class TripRoutePreviewsController{private final ExecutionPlanningUseCase useCase;private final CurrentActor actor;TripRoutePreviewsController(ExecutionPlanningUseCase u,CurrentActor a){useCase=u;actor=a;}@PostMapping List<ExecutionPlanningUseCase.DayRouteSummary>post(@PathVariable UUID tripId,@RequestBody(required=false) RouteMutation r){return useCase.tripRoutePreview(tripId,actor.requireUserId(),r==null?null:r.bufferMinutes());}}
record RouteMutation(Integer bufferMinutes){}
